var NLEHistory=class _NLEHistory{constructor(limit=80){this.limit=Math.max(1,Number(limit)||80),this.past=[],this.future=[]}record(state){this.past.push(_NLEHistory.clone(state)),this.past.length>this.limit&&this.past.shift(),this.future=[]}undo(currentState){return this.past.length?(this.future.push(_NLEHistory.clone(currentState)),this.past.pop()):null}redo(currentState){return this.future.length?(this.past.push(_NLEHistory.clone(currentState)),this.future.pop()):null}status(){return{canUndo:this.past.length>0,canRedo:this.future.length>0}}clear(){this.past=[],this.future=[]}static clone(value){return value===null||typeof value!="object"||typeof Blob<"u"&&value instanceof Blob?value:value instanceof Date?new Date(value.getTime()):Array.isArray(value)?value.map(item=>_NLEHistory.clone(item)):Object.fromEntries(Object.entries(value).map(([key,item])=>[key,_NLEHistory.clone(item)]))}};export{NLEHistory};
